public class ControllerJobTextObserver {
    public class Work implements Schedulable { public void execute(SchedulableContext context) {} }
    public static List<Object> observe() {
        List<Object> out = new List<Object>();
        String firstJob;
        String duplicateJob;
        List<String> cleanup = new List<String>();
        try {
            DispatchEntry__c row = new DispatchEntry__c(Name='Owned entry');
            insert row;
            ApexPages.StandardController controller = new ApexPages.StandardController(row);
            String fieldText = String.valueOf(row.Id);
            String shortened = fieldText.substring(0,15);
            String getter = controller.getId();
            Object dynamicGetter = controller.getId();
            String submitted = 't_' + controller.getId();
            String literal = '001000000000001';
            Id declaredId = literal;
            Object dynamicId = declaredId;
            out.add(fieldText);
            out.add(shortened);
            out.add(new List<Object>{getter, getter.length(), EncodingUtil.convertToHex(Blob.valueOf(getter)), dynamicGetter instanceof String, dynamicGetter instanceof Id});
            out.add(submitted);
            firstJob = System.schedule(submitted, '0 0 0 1 1 ? 2099', new Work());
            out.add([SELECT CronJobDetail.Name FROM CronTrigger WHERE Id=:firstJob].CronJobDetail.Name);
            try {
                duplicateJob = System.schedule(submitted, '0 0 0 1 1 ? 2099', new Work());
                out.add(new List<String>{'ACCEPTED'});
            } catch (Exception fault) {
                out.add(new List<String>{fault.getTypeName(), fault.getMessage()});
            }
            out.add(new List<Object>{literal, literal.length(), String.valueOf(declaredId), String.valueOf(dynamicId), 't_' + literal, 't_' + declaredId});
        } catch (Exception fault) {
            out.add(new List<String>{'SETUP_ERROR', fault.getTypeName(), fault.getMessage()});
        } finally {
            for (String jobId : new List<String>{duplicateJob, firstJob}) {
                if (jobId == null) continue;
                try { System.abortJob(jobId); }
                catch (Exception fault) { cleanup.add(fault.getTypeName() + '|' + fault.getMessage()); }
            }
        }
        out.add(cleanup);
        return out;
    }
}

