public class ControllerJobTextObserver {
    public static List<Object> observe() {
        DispatchEntry__c row = new DispatchEntry__c(Name='Owned entry');
        insert row;
        String full = String.valueOf(row.Id);
        String shortText = full.substring(0,15);
        List<Object> out = new List<Object>();
        for (String supplied : new List<String>{shortText, full}) {
            ApexPages.StandardController controller = new ApexPages.StandardController(new DispatchEntry__c(Id=supplied));
            String getter = controller.getId();
            out.add(new List<Object>{supplied, supplied.length(), getter, getter.length(), 't_' + controller.getId()});
        }
        return out;
    }
}
